L13_1 = "<b><color=#4EC2F3>[\236\132\156\237\130\183 \235\167\129\237\129\172 \236\139\156\236\138\164\237\133\156]</color></b>\n<color=#FFCF3B>- \237\133\140\235\157\188\235\184\140\235\160\136\236\157\184\236\157\152 \236\176\168\236\155\144 \235\182\132\236\132\157 \237\154\140\235\161\156\235\165\188 \237\153\156\236\132\177\237\153\148\237\149\160 \235\141\176\236\157\180\237\132\176\235\165\188 \235\170\168\236\156\188\234\179\160, \235\182\132\236\132\157\237\149\152\236\132\184\236\154\148.</color>\n<color=#FFCF3B>- \235\185\153\234\179\160\235\165\188 \236\153\132\236\132\177\237\149\152\236\151\172 \235\179\180\236\131\129\236\157\132 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\235\138\148 \237\138\185\235\179\132\237\149\156 \236\157\180\235\178\164\237\138\184\236\158\133\235\139\136\235\139\164.</color>\n\n<b><color=#FFFFFF>[\235\141\176\236\157\180\237\132\176 \235\182\132\236\132\157]</color></b>\n<color=#F2F2F2>- <color=#FFCF3B>\237\157\169\236\150\180\236\167\132 \234\184\176\235\161\157</color>\236\157\128 EP2 \236\157\180\236\131\129\236\157\152 \235\169\148\236\157\184\236\138\164\237\138\184\235\166\188/\236\158\144\236\156\160\234\179\132\236\149\189/\235\179\180\234\184\137\236\158\145\236\160\132/\236\157\180\235\178\164\237\138\184 \236\177\140\235\166\176\236\167\128/\236\157\180\235\178\164\237\138\184 \236\151\144\237\148\188\236\134\140\235\147\156\236\151\144\236\132\156 \236\157\188\236\160\149 \237\153\149\235\165\160\235\161\156 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.</color>\n<color=#F2F2F2>- <color=#FFCF3B>\237\157\169\236\150\180\236\167\132 \234\184\176\235\161\157</color> 1\234\176\156\235\165\188 \236\134\140\235\170\168\237\149\180 \235\141\176\236\157\180\237\132\176 \235\182\132\236\132\157\236\157\132 \237\149\152\235\169\180 \235\158\156\235\141\164\237\149\156 \236\136\171\236\158\144\235\165\188 \237\154\141\235\147\157\237\149\160 \236\136\15