1\156\235\138\148 \234\176\156\235\176\169\235\144\152\236\167\128 \236\149\138\236\138\181\235\139\136\235\139\164.</color>\n\n<b><color=#FFFFFF>[\235\179\180\236\131\129]</color></b>\n<color=#F2F2F2>- \234\176\153\236\157\128 \236\164\132 \237\152\185\236\157\128 \235\140\128\234\176\129\236\132\160\236\151\144 \236\156\132\236\185\152\237\149\156 \235\141\176\236\157\180\237\132\176\235\165\188 \235\170\168\235\145\144 \234\176\156\235\176\169\237\149\152\235\169\180 <color=#FFCF3B>\235\185\153\234\179\160</color>\234\176\128 \235\144\169\235\139\136\235\139\164.</color>\n<color=#F2F2F2>- \235\185\153\234\179\160\235\165\188 \236\153\132\236\132\177\237\149\152\235\169\180 \234\176\129 \236\164\132\236\151\144 \237\149\180\235\139\185\237\149\152\235\138\148 <color=#FFCF3B>\235\185\153\234\179\160\236\153\132\236\132\177 \235\179\180\236\131\129</color>\236\157\132 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.</color>\n<color=#F2F2F2>- \236\153\132\236\132\177\237\149\156 \235\185\153\234\179\160 \236\164\132\236\157\152 \234\176\156\236\136\152\234\176\128 \235\136\132\236\160\129\235\144\152\235\169\180 <color=#FFCF3B>\235\136\132\236\160\129 \235\185\153\234\179\160\235\179\180\236\131\129</color>\236\157\132 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.</color>"
