L19_1 = "<b><color=#4EC2F3>[{0}]</color></b>\n<color=#FFCF3B>- {1}\236\157\132 \235\170\168\236\156\188\234\179\160, \235\182\132\236\132\157\237\149\152\236\132\184\236\154\148.</color>\n<color=#FFCF3B>- \235\185\153\234\179\160\235\165\188 \236\153\132\236\132\177\237\149\152\236\151\172 \235\179\180\236\131\129\236\157\132 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\235\138\148 \237\138\185\235\179\132\237\149\156 \236\157\180\235\178\164\237\138\184\236\158\133\235\139\136\235\139\164.</color>\n\n<b><color=#FFFFFF>[\235\141\176\236\157\180\237\132\176 \235\182\132\236\132\157]</color></b>\n<color=#F2F2F2>- <color=#FFCF3B>{1}</color>\236\157\128 \235\169\148\236\157\184\236\138\164\237\138\184\235\166\188(EP.1 \235\179\180\237\134\181 \235\130\156\236\157\180\235\143\132 \236\160\156\236\153\184)/\236\132\156\235\184\140\236\138\164\237\138\184\235\166\188(\236\132\156\237\148\140\235\166\172\235\168\188\237\138\184 \236\160\156\236\153\184) \235\147\177 \236\157\180\237\132\176\235\139\136\236\155\128 \236\134\140\235\170\168\237\149\152\235\138\148 \234\179\179\236\151\144\236\132\156 \236\157\188\236\160\149 \237\153\149\235\165\160\235\161\156 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.</color>\n<color=#F2F2F2>- <color=#FFCF3B>{1}</color> 1\234\176\156\235\165\188 \236\134\140\235\170\168\237\149\180 \235\141\176\236\157\180\237\132\176 \235\182\132\236\132\157\236\157\132 \237\149\152\235\169\180 \235\158\156\235\141\164\237\149\156 \236\136\171\236\158\144\235\165\188 \237\154\141\235\147\157\237\149\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164</color>\n<color=#F2F2F2>- \236\136\171\236\158\144\235\165\188 \236\181\156\236\180\136\235\161\156 \237\154\141\235\147\157\237\149\152\235\169\180 \237\149\180\235\139\185 \236\185\184\236\157\180 \234\176\156\235\176\169\235\144\169\235\139\136\235\139\164.</color>\n<color=#F2F2F2>- \236\130\172\236\154\169\237\149\152\